def accepted_red(stage, seal):
    receipt_path = HERE / 'validation' / stage / 'validation-receipt.json'
    receipt = json.loads(receipt_path.read_text())
    if receipt.get('mode') != 'red' or receipt.get('passedStage') is not True:
        raise ValueError(f'Accepted red evidence required: {receipt_path}')
    if sha(seal) != receipt['contractSealSha256']:
        raise ValueError(f'Red evidence does not pin the current seal: {seal}')
    return receipt_path


